css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-hoff .btn{display:inline-flex;align-items:center;justify-content:center;gap:.5em;padding:.9em 1.5em;border-radius:var(--radius);font:700 .95em var(--font-body);text-decoration:none;border:1.5px solid var(--primary);background:var(--primary);color:var(--on-primary);cursor:pointer;transition:transform calc(.25s/var(--speed)),box-shadow calc(.25s/var(--speed))}
.fx-hoff .btn:hover{transform:translateY(-2px);box-shadow:0 12px 24px -14px var(--primary)}
.fx-hoff .btn.ghost{background:transparent;color:var(--primary)}
.fx-hoff .btn:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fx-hoff{position:relative;overflow:hidden;background:var(--surface);display:flex;flex-direction:column}
.fx-hoff .hd{display:flex;align-items:center;justify-content:space-between;padding:1.3em max(5vw,1.25em)}
.fx-hoff .logo{display:inline-flex;align-items:center;gap:.55em;font:600 1.5em var(--font-heading);color:var(--text);text-decoration:none}
.fx-hoff .logo i{width:.8em;height:.8em;border-radius:30%;background:linear-gradient(135deg,var(--primary),var(--accent))}
.fx-hoff .bg{display:inline-flex;align-items:center;gap:.7em;padding:.6em .9em;border:1px solid var(--border);border-radius:999px;background:transparent;color:var(--text);font:700 .88em var(--font-body);cursor:pointer;transition:background .2s}
.fx-hoff .bg:hover{background:color-mix(in srgb,var(--text) 6%,transparent)}
.fx-hoff .bars{display:grid;gap:.3em;width:1.2em}.fx-hoff .bars i{height:1.6px;background:currentColor;border-radius:2px}.fx-hoff .bars i:last-child{width:70%;justify-self:end}
.fx-hoff button:focus-visible,.fx-hoff .dr a:focus-visible,.fx-hoff .logo:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fx-hoff .main{flex:1;display:grid;align-content:center;justify-items:start;gap:1.2em;width:min(980px,100%);margin:0 auto;padding:2em 1.25em 5em}
.fx-hoff .main .k{font-size:.78em;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--accent)}
.fx-hoff .main h1{font-size:clamp(2.4em,6vw,4.6em);max-width:12em}.fx-hoff .main p{opacity:.7;max-width:44ch;font-size:1.1em}
.fx-hoff .ov{position:absolute;inset:0;z-index:40;background:color-mix(in srgb,var(--text) 50%,transparent);opacity:0;visibility:hidden;transition:opacity calc(.35s/var(--speed)),visibility 0s calc(.35s/var(--speed));-webkit-backdrop-filter:blur(2px);backdrop-filter:blur(2px)}
.fx-hoff .dr{position:absolute;z-index:41;top:0;right:0;bottom:0;width:min(400px,88%);background:var(--surface);color:var(--text);border-left:1px solid var(--border);padding:1.3em 1.8em 1.8em;display:flex;flex-direction:column;transform:translateX(102%);visibility:hidden;transition:transform calc(.5s/var(--speed)) cubic-bezier(.7,0,.2,1),visibility 0s calc(.5s/var(--speed));box-shadow:-30px 0 60px -30px rgba(0,0,0,.4)}
.fx-hoff.is-open .ov{opacity:1;visibility:visible;transition-delay:0s}.fx-hoff.is-open .dr{transform:none;visibility:visible;transition-delay:0s}
.fx-hoff .dh{display:flex;justify-content:space-between;align-items:center;margin-bottom:1.6em}.fx-hoff .dh span{font-size:.75em;font-weight:700;letter-spacing:.16em;text-transform:uppercase;opacity:.55}
.fx-hoff .cl{width:2.5em;height:2.5em;border-radius:50%;border:1px solid var(--border);background:transparent;color:var(--text);font-size:1em;cursor:pointer;position:relative}
.fx-hoff .cl::before,.fx-hoff .cl::after{content:"";position:absolute;left:50%;top:50%;width:1em;height:1.6px;background:currentColor;transform:translate(-50%,-50%) rotate(45deg)}.fx-hoff .cl::after{transform:translate(-50%,-50%) rotate(-45deg)}
.fx-hoff .dr ul{list-style:none;margin:0;padding:0;display:grid}
.fx-hoff .dr li{border-bottom:1px solid var(--border);opacity:0;transform:translateX(24px);transition:opacity calc(.4s/var(--speed)),transform calc(.5s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-hoff.is-open .dr li{opacity:1;transform:none;transition-delay:calc(.15s/var(--speed) + var(--i)*70ms/var(--speed))}
.fx-hoff .dr li a{display:flex;justify-content:space-between;align-items:baseline;padding:.75em 0;font:600 1.9em var(--font-heading);color:var(--text);text-decoration:none;transition:color .2s,padding-left calc(.3s/var(--speed))}
.fx-hoff .dr li a small{font:700 .38em var(--font-body);opacity:.45;letter-spacing:.1em}
.fx-hoff .dr li a:hover{color:var(--primary);padding-left:.3em}
.fx-hoff .df{margin-top:auto;display:grid;gap:.4em;font-size:.88em;opacity:.7;padding-top:1.4em}
@media(prefers-reduced-motion:reduce){.fx-hoff .ov,.fx-hoff .dr,.fx-hoff .dr li{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-hoff .btn.is-tap{transform:translateY(-2px);box-shadow:0 12px 24px -14px var(--primary)}
.fx-hoff .bg.is-tap{background:color-mix(in srgb,var(--text) 6%,transparent)}
.fx-hoff .dr li a.is-tap{color:var(--primary);padding-left:.3em}
